<script setup lang="ts">
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useForm } from 'vee-validate'
import { formSchema } from '@/lib/form-schema'
import { z } from 'zod'
import { Plus, Layers, Users, ShieldCheck, LayoutDashboard } from '@lucide/vue'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import PageHeader from '@/components/business/PageHeader.vue'
import DataTable from '@/components/business/DataTable.vue'
import PermissionTree from '@/components/business/PermissionTree.vue'
import EditorDialog from '@/components/business/EditorDialog.vue'
import StatusBadge from '@/components/business/StatusBadge.vue'
import DisplaySettings from '@/components/DisplaySettings.vue'
import { notify, confirmAction } from '@/lib/feedback'
const { t } = useI18n(), active = ref('users'), editor = ref(false), page = ref(1), size = ref(20), enabled = ref(true), selected = ref(['1', '11'])
const { defineField, handleSubmit, errors, meta, resetForm } = useForm({ validationSchema: computed(() => formSchema<{ name: string }>(z.object({ name: z.string().trim().min(1, t('common.required')) }))), initialValues: { name: '' } })
const [name, nameAttrs] = defineField('name')
const rows = computed(() => [{ id: '9007199254740993121', name: '陈知远', username: 'chen.zhiyuan', email: 'zhiyuan@example.test', enabled: true }, { id: '9007199254740993122', name: '林予安', username: 'lin.yuan', email: 'yuan@example.test', enabled: true }, { id: '9007199254740993123', name: '周明', username: 'zhou.ming', email: 'ming@example.test', enabled: false }])
const columns = computed(() => [{ key: 'name', title: t('common.name'), width: 160 }, { key: 'username', title: t('auth.username'), width: 160 }, { key: 'email', title: t('iam.fields.email'), width: 200 }, { key: 'enabled', title: t('common.status') }, { key: 'actions', title: t('common.actions'), width: 120 }])
const nodes = computed(() => [{ id: '1', name: t('iam.user'), children: [{ id: '11', name: t('common.search') }, { id: '12', name: t('common.create') }, { id: '13', name: t('common.edit') }] }, { id: '2', name: t('iam.role'), children: [{ id: '21', name: t('iam.grant') }, { id: '22', name: t('common.remove'), disabled: true }] }])
const save = handleSubmit(() => { notify(t('common.saved')); editor.value = false; resetForm() })
function edit(value = '') { resetForm({ values: { name: value } }); editor.value = true }
async function remove() { if (await confirmAction(t('common.deleteConfirm'), t('common.confirm'), true)) notify(t('common.deleted')) }
</script>
<template>
  <div class="min-h-dvh md:grid md:grid-cols-[220px_minmax(0,1fr)]"><aside class="hidden border-r bg-card p-5 md:block"><div class="mb-10 flex items-center gap-3"><div class="rounded-xl bg-primary p-2 text-primary-foreground"><Layers class="size-5" /></div><strong>{{ t('common.shortBrand') }}</strong></div><p class="mb-4 text-xs text-muted-foreground">{{ t('common.designPreview') }}</p><button v-for="item in [{ id: 'users', label: 'common.sampleUsers', icon: Users }, { id: 'roles', label: 'common.sampleRoles', icon: ShieldCheck }, { id: 'workspace', label: 'common.sampleWorkspace', icon: LayoutDashboard }]" :key="item.id" class="mb-1 flex min-h-11 w-full items-center gap-3 rounded-lg px-3 text-left text-sm" :class="active === item.id ? 'bg-accent font-medium text-accent-foreground' : 'text-muted-foreground hover:bg-muted'" @click="active = item.id"><component :is="item.icon" class="size-4" />{{ t(item.label) }}</button></aside><div class="min-w-0"><header class="flex min-h-16 items-center justify-between gap-3 border-b bg-card px-5"><span class="text-sm text-muted-foreground">{{ t('common.componentGallery') }}</span><div class="flex items-center gap-2"><Badge variant="outline">{{ t('common.designPreview') }}</Badge><DisplaySettings /></div></header><main class="mx-auto max-w-6xl p-4 md:p-7"><PageHeader :eyebrow="t('common.workspaceEyebrow')" :title="t('common.' + (active === 'users' ? 'sampleUsers' : active === 'roles' ? 'sampleRoles' : 'sampleWorkspace'))" :description="t('common.sampleHint')"><Button @click="edit()"><Plus class="size-4" />{{ t('common.create') }}</Button></PageHeader><Tabs v-model="active"><TabsList class="mb-5 md:hidden"><TabsTrigger value="users">{{ t('iam.user') }}</TabsTrigger><TabsTrigger value="roles">{{ t('iam.role') }}</TabsTrigger><TabsTrigger value="workspace">{{ t('common.home') }}</TabsTrigger></TabsList><TabsContent value="users"><div class="mb-4 flex flex-wrap items-center gap-2"><Input :placeholder="t('common.search')" :aria-label="t('common.search')" class="w-full sm:w-72" /><Button variant="secondary">{{ t('common.search') }}</Button><Button variant="ghost">{{ t('common.reset') }}</Button></div><DataTable :page-sizes="[10, 20, 50, 100, 200]" v-model:page="page" v-model:size="size" :rows="rows" :columns="columns" :total="3" selectable><template #name="{ row }"><div class="flex items-center gap-3"><span class="flex size-8 shrink-0 items-center justify-center rounded-full bg-accent text-xs font-medium text-accent-foreground">{{ row.name.slice(0, 1) }}</span><span class="font-medium">{{ row.name }}</span></div></template><template #enabled="{ row }"><StatusBadge :label="t(row.enabled ? 'common.enabled' : 'common.disabled')" :tone="row.enabled ? 'success' : 'neutral'" /></template><template #actions="{ row }"><div class="flex gap-1"><Button variant="ghost" size="sm" @click="edit(row.name)">{{ t('common.edit') }}</Button><Button variant="ghost" size="sm" class="text-destructive" @click="remove">{{ t('common.remove') }}</Button></div></template></DataTable></TabsContent><TabsContent value="roles"><div class="grid gap-5 lg:grid-cols-[240px_1fr]"><Card class="h-fit shadow-none"><CardHeader><CardTitle class="text-base">{{ t('iam.role') }}</CardTitle></CardHeader><CardContent><div class="rounded-lg bg-accent px-3 py-3 text-sm font-medium text-accent-foreground">{{ t('common.sampleRoles') }}</div><p class="mt-4 text-xs text-muted-foreground">{{ t('common.editorHint') }}</p></CardContent></Card><div><PermissionTree v-model="selected" :nodes="nodes" /><div class="mt-4 flex justify-end gap-2"><Button variant="outline">{{ t('common.cancel') }}</Button><Button @click="notify(t('common.saved'))">{{ t('common.save') }}</Button></div></div></div></TabsContent><TabsContent value="workspace"><div class="grid gap-4 sm:grid-cols-3"><Card v-for="(label, index) in ['iam.user', 'iam.role', 'workspace.pending']" :key="label" class="shadow-none"><CardContent><p class="text-sm text-muted-foreground">{{ t(label) }}</p><p class="mt-4 text-3xl font-semibold tabular-nums">{{ [128, 12, 8][index] }}</p></CardContent></Card></div><div class="mt-5 grid gap-5 lg:grid-cols-[1.4fr_1fr]"><Card class="shadow-none"><CardHeader><CardTitle>{{ t('workspace.pending') }}</CardTitle></CardHeader><CardContent><div v-for="row in rows" :key="row.id" class="flex items-center justify-between border-b py-4 last:border-0"><span>{{ row.name }}</span><StatusBadge :label="t('common.enabled')" tone="success" /></div></CardContent></Card><Card class="shadow-none"><CardHeader><CardTitle>{{ t('workspace.shortcuts') }}</CardTitle></CardHeader><CardContent class="flex flex-wrap gap-2"><Button variant="outline" @click="active = 'users'">{{ t('iam.user') }}</Button><Button variant="outline" @click="active = 'roles'">{{ t('iam.role') }}</Button></CardContent></Card></div></TabsContent></Tabs></main></div><EditorDialog v-model="editor" :title="t('common.edit')" :dirty="meta.dirty" @save="save"><form class="space-y-5" @submit.prevent="save"><div class="space-y-2"><Label for="sample-name">{{ t('common.name') }}</Label><Input id="sample-name" v-model="name" v-bind="nameAttrs" :aria-invalid="!!errors.name" aria-describedby="sample-name-error" /><p v-if="errors.name" id="sample-name-error" class="text-sm text-destructive" role="alert">{{ errors.name }}</p></div><div class="flex items-center justify-between"><Label for="sample-enabled">{{ t('common.status') }}</Label><Switch id="sample-enabled" v-model="enabled" /></div></form></EditorDialog></div>
</template>
